      ).toThrow(RangeError);
    });

    it("rejects negative rate for a region", () => {
      expect(
        () => new RegionalTaxCalculator({ US: -0.1 }),
      ).toThrow(RangeError);
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(() => new RegionalTaxCalculator({ US: 0, FR: 1 }, 0)).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it("looks up region rate and rounds down", () => {
      // 8.75% of 1000 = 87.5 → 87
      expect(calc.computeTaxCents(1000, "US-CA")).toBe(87);
    });

    it("uses FR rate", () => {
      // 20% of 1000 = 200
      expect(calc.computeTaxCents(1000, "FR")).toBe(200);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 1000 = 50
      expect(calc.computeTaxCents(1000, "JP")).toBe(50);
    });

    it("returns 0 for zero taxable", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(calc.computeTaxCents(-1000, "US-CA")).toBe(0);
    });

    it("rounds down fractional cents", () => {
      // 8.75% of 101 = 8.8375 → 8
      expect(calc.computeTaxCents(101, "US-CA")).toBe(8);
    });

    it("default rate of 0 produces no tax for unknown regions", () => {
      const zeroDefault = new RegionalTaxCalculator({ US: 0.1 });
