    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  const lines: CartLine[] = [
    { product: { id: "p1", name: "Widget", unitPriceCents: 100 }, quantity: 2 },
    { product: { id: "p2", name: "Gadget", unitPriceCents: 200, weightGrams: 50 }, quantity: 1 },
  ];

  it("updates unitPriceCents from the fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(150)
        .mockResolvedValueOnce(250),
    };
    const result = await refreshPrices(lines, fetcher);
    expect(result).toHaveLength(2);
    expect(result[0].product.unitPriceCents).toBe(150);
    expect(result[0].quantity).toBe(2);
    expect(result[1].product.unitPriceCents).toBe(250);
    expect(result[1].product.weightGrams).toBe(50); // preserved
  });

  it("preserves product properties other than unitPriceCents", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const result = await refreshPrices(lines, fetcher);
    expect(result[0].product.name).toBe("Widget");
    expect(result[0].product.id).toBe("p1");
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("service down");
  });

  it("handles empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("calls fetcher with each product id in order", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(100),
    };
    await refreshPrices(lines, fetcher);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledTimes(2);
    expect(fetcher.fetchPriceCents).toHaveBeenNthCalledWith(1, "p1");
    expect(fetcher.fetchPriceCents).toHaveBeenNthCalledWith(2, "p2");
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const widget: Product = { id: "w1", name: "Widget", unitPriceCents: 1000, weightGrams: 200 };
const gadget: Product = { id: "g1", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(widget, 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities when adding the same product twice", () => {
      const cart = new Cart();
      cart.add(widget, 2);
      cart.add(widget, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects zero quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(widget, 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(widget, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      const bad: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
      expect(() => cart.add(bad, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(widget, 1);
      expect(cart.remove(widget.id)).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates the quantity of an existing product", () => {
      const cart = new Cart();
      cart.add(widget, 2);
      cart.updateQuantity(widget.id, 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(widget, 3);
      cart.updateQuantity(widget.id, 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove(widget.id)).toBe(false);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nope", 1)).toThrow(
        "Product nope is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(widget, 1);
      expect(() => cart.updateQuantity(widget.id, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(widget, 1);
      expect(() => cart.updateQuantity(widget.id, 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(widget, 2);
      cart.add(gadget, 1);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that does not mutate cart state", () => {
      const cart = new Cart();
      cart.add(widget, 1);
      const snap = cart.snapshot();
      snap[0].quantity = 999;
      expect(cart.itemCount).toBe(1);
    });
  });

  describe("totals — pricing pipeline", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(widget, 2); // 2000
      cart.add(gadget, 1); // 2000
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(4000);
    });

    it("applies discount from the policy", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy: mockDiscount });
      cart.add(widget, 2); // subtotal 2000
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500);
      expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(2000);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(widget, 1); // subtotal 1000
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1000);
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(widget, 1);
      expect(cart.totals().discountCents).toBe(0);
    });

    it("computes tax on the discounted subtotal", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(75),
      };
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        taxCalculator: mockTax,
        region: "US-CA",
      });
      cart.add(widget, 2); // subtotal 2000, discount 500, discounted 1500
      const totals = cart.totals();
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(1500, "US-CA");
      expect(totals.taxCents).toBe(75);
    });

    it("clamps negative tax to 0", () => {
      const negTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator: negTax });
      cart.add(widget, 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("computes shipping against lines and discounted subtotal", () => {
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(599),
      };
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        shippingCalculator: mockShipping,
      });
      cart.add(widget, 1); // subtotal 1000, discount 200, discounted 800
      const totals = cart.totals();
      expect(mockShipping.computeShippingCents).toHaveBeenCalled();
      const callArgs = (mockShipping.computeShippingCents as ReturnType<typeof vi.fn>).mock.calls[0];
      expect(callArgs[1]).toBe(800); // discounted subtotal
      expect(totals.shippingCents).toBe(599);
    });

    it("clamps negative shipping to 0", () => {
      const negShip: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator: negShip });
      cart.add(widget, 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(300),
      };
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(70),
      };
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        taxCalculator: mockTax,
        shippingCalculator: mockShipping,
      });
      cart.add(widget, 2); // subtotal 2000
      const totals = cart.totals();
      // discountedSubtotal = 2000 - 300 = 1700
      // total = 1700 + 70 + 500 = 2270
      expect(totals.totalCents).toBe(2270);
    });

    it("empty cart produces all-zero totals", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("defaults to US region", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: mockTax });
      cart.add(widget, 1);
      cart.totals();
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
    });
  });

  describe("checkout", () => {
    it("returns totals and lines for a basic checkout", async () => {
      const cart = new Cart();
      cart.add(widget, 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
    });

    it("refreshes prices via priceFetcher", async () => {
      const cart = new Cart();
      cart.add(widget, 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
      expect(result.lines[0].product.unitPriceCents).toBe(1500);
    });

    it("checks inventory and passes when available", async () => {
      const cart = new Cart();
      cart.add(widget, 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(inventoryChecker.check).toHaveBeenCalledWith("w1", 2);
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(widget, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
