      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("g1");
        expect((err as InventoryError).message).toBe("discontinued");
      }
    });

    it("does not mutate internal cart state after checkout", async () => {
      const cart = new Cart();
      cart.add(widget, 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(5000),
      };
      await cart.checkout({ priceFetcher });
      // Cart's internal lines should still have original price
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(2000);
    });
  });
});
